<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuth} from '../stores/auth'
import {useResource,money,number,dateTime} from '../composables/useResource'
import ResourceState from './ResourceState.vue'
import StatusTag from './StatusTag.vue'
import DataTable from './DataTable.vue'
const props=defineProps<{kind:'orders'|'requests';id:string}>(),route=useRoute(),auth=useAuth(),page=ref(1)
const resource=useResource<any>(()=>`/trace/${props.kind}/${props.id}?page=${page.value}&size=20`,{summary:{},events:[],total:0,links:[],order_items:[]})
const labels:Record<string,string>={request_amount:'申请金额',original_amount:'原订单金额',closed_amount:'已关闭金额',return_amount:'退货冲减',effective_amount:'净采购订单额'}
const balances:Record<string,string>={amount:'退货后应付',paid_amount:'净实付',outstanding_amount:'应付未付',reserved_amount:'付款申请占用',available_amount:'可申请余额',refundable_amount:'待收退款'}
const summary=computed(()=>Object.entries(labels).filter(([key])=>resource.data.value.summary?.[key]!==undefined))
function link(path:string){const target=new URL(path,location.origin),origin=new URL(route.fullPath,location.origin);origin.searchParams.delete('return_to');target.searchParams.set('return_to',origin.pathname+origin.search);return target.pathname+target.search}
function canLink(path:string){const key=path.split('?')[0].split('/')[1]||'';return auth.hasMenu(key)&&auth.can(({orders:'order:read',requests:'request:read',finance:'finance:read',inventory:'inventory:read',contracts:'contract:read',projects:'project:read'} as Record<string,string>)[key]||'')}
watch(()=>[props.kind,props.id],()=>page.value=1)
</script>
<template><ResourceState :error="resource.error.value" :loading="resource.loading.value" @retry="resource.load"><div class="notice-strip">追溯规则 <span>只使用明确单据关联。退货不重新增加原订单待履行数量；补采需要新申请。</span></div><div class="mini-metrics"><div v-for="[key,label] in summary" :key="key"><span>{{label}}</span><b>{{money(resource.data.value.summary[key])}}</b></div><template v-if="resource.data.value.summary.payable"><div v-for="(label,key) in balances" :key="key"><span>{{label}}</span><b>{{money(resource.data.value.summary.payable[key])}}</b></div></template></div><div class="section-toolbar"><template v-for="item in resource.data.value.links" :key="item.id"><router-link v-if="canLink(item.path)" :to="link(item.path)" class="table-link">{{item.label}} →</router-link></template></div><DataTable v-if="resource.data.value.order_items?.length" :rows="resource.data.value.order_items" :search="false" :columns="[{key:'material_name',label:'材料'},{key:'quantity',label:'原始采购数量',number:true},{key:'closed_quantity',label:'关闭数量',number:true},{key:'received_quantity',label:'已收数量',number:true},{key:'returned_quantity',label:'退货数量',number:true},{key:'remaining_quantity',label:'待履行数量',number:true},{key:'unit',label:'单位'}]"/><p class="field-hint">{{resource.data.value.source_notice||'没有对应记录时不生成虚构事件；历史缺失的审批或操作人不推测补齐。'}}</p><el-empty v-if="!resource.data.value.total" description="暂无可读取的业务追溯记录" :image-size="60"/><el-timeline v-else><el-timeline-item v-for="event in resource.data.value.events" :key="event.id" :timestamp="dateTime(event.created_at)"><div class="trace-event-heading"><b>{{event.label}}</b><StatusTag v-if="event.status" :value="event.status"/></div><p><router-link v-if="canLink(event.path)" :to="link(event.path)" class="table-link">{{event.code}} →</router-link><span v-else>{{event.code}}</span></p><p class="field-hint">操作人：{{event.operator_name||'未记录操作人'}}<span v-if="event.amount!==undefined"> · 金额 ¥ {{money(event.amount)}}</span></p><p v-if="event.reason">{{event.reason}}</p><p v-for="(line,i) in event.lines" :key="i" class="field-hint">{{line.material_name}} · {{line.specification}} · {{number(line.quantity)}} {{line.unit}}</p></el-timeline-item></el-timeline><el-pagination v-if="resource.data.value.total" v-model:current-page="page" :page-size="20" :pager-count="5" :total="resource.data.value.total" layout="total, prev, pager, next" background/></ResourceState></template>
<style scoped>.trace-event-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.el-timeline-item p{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.section-toolbar a{display:inline-flex;padding:12px 0;min-height:44px}@media(max-width:767px){.el-timeline{padding-left:8px}.el-pagination{max-width:100%;overflow:auto}}</style>
